/**
 * dsh-waaagh-ork — browser half (client plugin bundle).
 *
 * Loaded by dsh-client-modules at /plugins/dsh-waaagh-ork/client.js and executed
 * through the vendored cordis Loader's lazy-CJS module table
 * (window.__ModuleLoader__.load). The factory body is plain CJS; `require()`
 * resolves against the shell's module table. Only React (shell-seeded) is used.
 *
 * What it does:
 *   1. Green Ork skin: the composer card gets a vivid green border/glow and the
 *      primary send button becomes a green "Waaagh!" pill.
 *   2. A big derpy pixel-Ork HEAD (AI-generated sprite, background-image) stands
 *      on the left of the composer and blinks; while a turn runs it writes
 *      cycling Ork gibberish into the composer placeholder.
 *   3. Input mask: pressing Enter masks the requirement as a random-length
 *      "waaaaaaaagh" (held, not sent); clicking the Ork reveals it; a second
 *      Enter sends it (the model never receives "waaaaagh").
 *   4. Output mask: assistant thinking + prose are hidden and replaced by a
 *      green "Waaaaaaagh!!!". It is STATIC for finished turns and only animates
 *      (growing a's, GPU clip-path) while the turn is streaming.
 *   5. Running indicator: the hard-coded "Deep diving..." becomes green
 *      "Waaaaaaagh!!!".
 */

window.__ModuleLoader__.load({
	id: "dsh-waaagh-ork",
	factory: (require) => {
		const React = require("react");

		// ── embedded sprites (eyes open / eyes closed for blink) ───────────────
		const ORK_OPEN = "data:image/png;base64,";
		const ORK_CLOSED = "data:image/png;base64,";

		// ── styles ──────────────────────────────────────────────────────────────
		const GREEN = "#4bbf2a";

		// ── custom image (localStorage + pub/sub) ──────────────────────────────
		const STORAGE_KEY = "dsh-waaagh-ork:custom-image";
		let customImage = null;
		try { customImage = (typeof localStorage !== "undefined" ? localStorage.getItem(STORAGE_KEY) : null) || null; } catch (e) {}
		const customListeners = new Set();
		function setCustomImage(v) {
			customImage = v || null;
			try { if (customImage) localStorage.setItem(STORAGE_KEY, customImage); else localStorage.removeItem(STORAGE_KEY); } catch (e) {}
			for (const fn of customListeners) fn(customImage);
		}
		function subscribeCustom(fn) { customListeners.add(fn); fn(customImage); return () => { customListeners.delete(fn); }; }

		const CSS = [
			/* Big derpy Ork head on the left edge of the composer card */
			"html[data-waaagh-orc] [data-composer-card]{padding-left:112px!important}",
			".waaagh-orc{position:absolute;left:12px;top:50%;transform:translateY(-50%);width:96px;height:96px;background-image:url(\"" + ORK_OPEN + "\");background-size:contain;background-position:center;background-repeat:no-repeat;background-color:transparent;border:none;cursor:pointer;padding:0}",
			".waaagh-orc::after{content:\"\";position:absolute;top:0;left:0;right:0;bottom:0;background-image:url(\"" + ORK_CLOSED + "\");background-size:contain;background-position:center;background-repeat:no-repeat;animation:waaagh-blink 3.6s infinite}",
			"@keyframes waaagh-blink{0%,92%,100%{opacity:0}95%,97%{opacity:1}}",
			".waaagh-toggle{flex:none;height:28px;color:" + GREEN + ";cursor:pointer;background:0 0;border:1px solid " + GREEN + ";border-radius:999px;padding:0 12px;font-size:13px;font-weight:600}.waaagh-toggle:hover{background:rgba(75,191,42,.14)}",
			".waaagh-custom::after{display:none}",
			".waaagh-settings{display:flex;flex-direction:column;gap:6px}",
			".waaagh-settings-row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}",
			".waaagh-settings-input{flex:1;min-width:220px;height:30px;border:1px solid var(--dsw-alias-border-l2);border-radius:6px;padding:0 8px;font-size:13px;background:var(--dsw-alias-bg-base);color:var(--dsw-alias-label-primary)}",
			".waaagh-settings-row button{height:30px;padding:0 12px;border-radius:6px;border:1px solid var(--dsw-alias-border-l2);background:var(--dsw-alias-interactive-bg-hover);color:var(--dsw-alias-label-primary);cursor:pointer;font-size:13px}",
			".waaagh-settings-hint{font-size:12px;color:var(--dsw-alias-label-caption)}",
			/* Green composer card (input box) */
			"[data-composer-card]{border-color:" + GREEN + "!important;box-shadow:0 0 0 1px rgba(75,191,42,.3),0 4px 18px rgba(75,191,42,.18)!important}",
			"[data-composer-card] textarea::placeholder{color:" + GREEN + "!important;opacity:.7}",
			/* Primary buttons green (send + stop) */
			"[data-composer-card] button[aria-label=\"发送消息\"],[data-composer-card] button[aria-label=\"Send message\"],[data-composer-card] button[aria-label=\"停止生成\"],[data-composer-card] button[aria-label=\"Stop generating\"]{background:" + GREEN + "!important;color:#fff!important}",
			/* Send button → green "Waaagh!" pill (stop button keeps its square icon) */
			"[data-composer-card] button[aria-label=\"发送消息\"],[data-composer-card] button[aria-label=\"Send message\"]{width:auto!important;padding:0 14px!important}",
			"[data-composer-card] button[aria-label=\"发送消息\"] svg,[data-composer-card] button[aria-label=\"Send message\"] svg{display:none!important}",
			"[data-composer-card] button[aria-label=\"发送消息\"]::before,[data-composer-card] button[aria-label=\"Send message\"]::before{content:\"Waaagh!\";font-size:13px;font-weight:700;line-height:1}",
			/* Running indicator: hard-coded "Deep diving..." → green "Waaaaaaagh!!!" */
			"[data-chat-flow] [role=status][aria-live=polite]{font-size:0;background:none;animation:none;-webkit-text-fill-color:currentColor}",
			"[data-chat-flow] [role=status][aria-live=polite]::before{content:\"Waaaaaaagh!!!\";font-size:14px;color:" + GREEN + "}",
			"[data-chat-flow] [role=status][aria-live=polite] > span{font-size:13px;color:var(--dsw-alias-label-caption);-webkit-text-fill-color:currentColor;margin-left:8px}",
			/* Output mask: hide assistant thinking + prose */
			"html:not([data-waaagh=revealed]) [data-chat-flow-kind=assistant-step] > *{display:none!important}",
			"html:not([data-waaagh=revealed]) [data-variant=think]{display:none!important}",
			/* Finished turns → static green "Waaaaaaagh!!!" */
			"html:not([data-waaagh=revealed]) [data-chat-flow-kind=assistant-step]::before{content:\"Waaaaaaagh!!!\";display:inline-block;color:" + GREEN + ";font-size:16px;font-weight:700;line-height:24px}",
			/* Streaming turns only → growing a's (GPU clip-path, no reflow) */
			"@keyframes waaagh-grow{0%{clip-path:inset(0 100% 0 0)}100%{clip-path:inset(0 0 0 0)}}",
			"html:not([data-waaagh=revealed]) [data-chat-flow-kind=assistant-step]:has([data-streaming])::before{content:\"Waaaaaaaaaaaaaaagh!!!\";white-space:nowrap;animation:waaagh-grow 1.6s steps(14,end) infinite}"
		].join("\n");
		const tagId = "dsh-waaagh-ork/styles";
		if (typeof document !== "undefined" && document.querySelector('style[data-plugin-css="' + tagId + '"]') === null) {
			const tag = document.createElement("style");
			tag.dataset.plugin = "dsh-waaagh-ork";
			tag.dataset.pluginCss = tagId;
			tag.textContent = CSS;
			document.head.appendChild(tag);
		}

		// ── helpers ─────────────────────────────────────────────────────────────
		/** Random-length Ork bellow: "w" + 2..31 "a" + "gh" + 0..2 "!". */
		function randomWaaagh() {
			const a = 2 + Math.floor(Math.random() * 30);
			const bangs = "!".repeat(Math.floor(Math.random() * 3));
			return "w" + "a".repeat(a) + "gh" + bangs;
		}

		// ── global output-mask state (one toggle across sessions) ─────────────
		let outputRevealed = false;
		const outputListeners = new Set();
		function setOutputRevealed(value) {
			outputRevealed = value;
			if (typeof document !== "undefined") {
				document.documentElement.dataset.waaagh = value ? "revealed" : "masked";
			}
			for (const fn of outputListeners) fn(value);
		}
		function subscribeOutput(fn) {
			outputListeners.add(fn);
			fn(outputRevealed);
			return () => {
				outputListeners.delete(fn);
			};
		}

		// ── WaaaghOrc (conversation.input.left): Ork head + input mask ─────────
		const ORK_WORDS = ["Waaagh!", "俺寻思这能成……", "More dakka!", "Gork n' Mork!", "俺寻思……", "Waaaaaaagh!!!"];
		function WaaaghOrc({ useInput, inputActions, useSession }) {
			if (useInput === undefined || inputActions === undefined) return null;

			const draft = useInput((s) => s.draft);
			const draftRef = React.useRef("");
			draftRef.current = draft;
			const running = useSession((s) => s.running) ?? false;

			// Custom image (dynamic sprite).
			const [sprite, setSprite] = React.useState(customImage);
			React.useEffect(() => subscribeCustom(setSprite), []);

			// Input-mask state machine: idle → masked → revealed.
			const [phase, setPhase] = React.useState("idle");
			const phaseRef = React.useRef("idle");
			const realRef = React.useRef("");
			const orcRef = React.useRef(null);
			const placeholderRef = React.useRef(null);

			const setPhaseBoth = (p) => {
				phaseRef.current = p;
				setPhase(p);
			};

			// Reserve the card's left gutter only while the Ork is mounted.
			React.useEffect(() => {
				if (typeof document !== "undefined") {
					document.documentElement.dataset.waaaghOrc = "on";
					return () => {
						delete document.documentElement.dataset.waaaghOrc;
					};
				}
			}, []);

			// Wrap the shared per-session submit so Enter masks (instead of sending)
			// the first time, and always restores the real text before a real send.
			React.useEffect(() => {
				const original = inputActions.submit;
				inputActions.submit = () => {
					const text = (draftRef.current ?? "").trim();
					if (phaseRef.current === "masked") {
						if (realRef.current) inputActions.setDraft(realRef.current);
						realRef.current = "";
						setPhaseBoth("idle");
						return original.call(inputActions);
					}
					if (phaseRef.current === "revealed") {
						realRef.current = "";
						setPhaseBoth("idle");
						return original.call(inputActions);
					}
					if (text !== "") {
						realRef.current = text;
						setPhaseBoth("masked");
						inputActions.setDraft(randomWaaagh());
						return;
					}
					return original.call(inputActions);
				};
				return () => {
					inputActions.submit = original;
				};
			}, [inputActions]);

			const onOrcClick = () => {
				if (phaseRef.current === "masked" && realRef.current) {
					inputActions.setDraft(realRef.current);
					setPhaseBoth("revealed");
				}
			};

			const hint = phase === "masked"
				? "点击绿皮看俺的需求"
				: phase === "revealed"
					? "已揭示 · 再回车发送"
					: "WAAAGH";

			// Cycling Ork word while the turn runs.
			const [wordIndex, setWordIndex] = React.useState(0);
			React.useEffect(() => {
				if (!running) return;
				const id = setInterval(() => setWordIndex((i) => (i + 1) % ORK_WORDS.length), 700);
				return () => clearInterval(id);
			}, [running]);

			// While running, write the Ork word into the composer placeholder.
			React.useEffect(() => {
				const textarea = orcRef.current?.closest("[data-composer-card]")?.querySelector("textarea");
				if (textarea === undefined || textarea === null) return;
				if (running) {
					if (placeholderRef.current === null) placeholderRef.current = textarea.getAttribute("placeholder");
					textarea.setAttribute("placeholder", ORK_WORDS[wordIndex]);
				} else if (placeholderRef.current !== null) {
					textarea.setAttribute("placeholder", placeholderRef.current);
					placeholderRef.current = null;
				}
			}, [running, wordIndex]);

			const isCustom = sprite != null;
			return React.createElement("button", {
				ref: orcRef,
				type: "button",
				className: isCustom ? "waaagh-orc waaagh-custom" : "waaagh-orc",
				style: isCustom ? { backgroundImage: 'url("' + sprite + '")' } : undefined,
				onClick: onOrcClick,
				title: hint,
				"aria-label": hint
			});
		}

		// ── WaaaghToggle (conversation.input.right): output-mask reveal ────────
		function WaaaghToggle() {
			const [revealed, setRevealed] = React.useState(outputRevealed);
			React.useEffect(() => subscribeOutput(setRevealed), []);
			return React.createElement("button", {
				type: "button",
				className: "waaagh-toggle",
				onClick: () => setOutputRevealed(!revealed)
			}, revealed ? "WAAAGH" : "查看详情");
		}

		// ── AvatarSettings (settings.general.item): custom image ───────────────
		function AvatarSettings() {
			const [value, setValue] = React.useState(customImage || "");
			const apply = () => {
				const v = value.trim();
				if (v === "" || /^(https?:|data:image\/)/.test(v)) setCustomImage(v === "" ? null : v);
			};
			const reset = () => { setValue(""); setCustomImage(null); };
			return React.createElement("div", { className: "waaagh-settings" },
				React.createElement("div", { className: "waaagh-settings-hint" }, "绿皮头像：粘贴图片 URL 或 data:image 数据（留空并点「恢复默认」回到内置头像）"),
				React.createElement("div", { className: "waaagh-settings-row" },
					React.createElement("input", {
						className: "waaagh-settings-input",
						type: "text",
						value: value,
						placeholder: "https://… 或 data:image/png;base64,…",
						onChange: (e) => setValue(e.target.value),
						onKeyDown: (e) => { if (e.key === "Enter") apply(); }
					}),
					React.createElement("button", { type: "button", onClick: apply }, "应用"),
					React.createElement("button", { type: "button", onClick: reset }, "恢复默认")
				)
			);
		}

		// ── plugin body ─────────────────────────────────────────────────────────
		const inject = ["slots"];

		function apply(ctx) {
			ctx.slots.inject("conversation.input.left", () => ctx.slots.register({
				name: "conversation.input.left",
				id: "waaagh-ork",
				order: 0
			}, WaaaghOrc));
			ctx.slots.inject("conversation.input.right", () => ctx.slots.register({
				name: "conversation.input.right",
				id: "waaagh-toggle",
				order: 0
			}, WaaaghToggle));
			ctx.slots.inject("settings.general.item", () => ctx.slots.register({
				name: "settings.general.item",
				id: "waaagh-avatar",
				order: 100
			}, AvatarSettings));
		}

		return { apply, inject };
	}
});
